252	   * Registers a tool definition.
253	   *
254	   * Note that excluded tools are still registered to allow for enabling them
255	   * later in the session.
256	   *
257	   * @param tool - The tool object containing schema and execution logic.
258	   */
259	  registerTool(tool: AnyDeclarativeTool): void {
260	    if (this.allKnownTools.has(tool.name)) {
