278	  /**
279	   * Sorts tools as:
280	   * 1. Built in tools.
281	   * 2. Discovered tools.
282	   * 3. MCP tools ordered by server name.
283	   *
284	   * This is a stable sort in that tries preserve existing order.
285	   */
286	  sortTools(): void {
287	    const getPriority = (tool: AnyDeclarativeTool): number => {
288	      if (tool instanceof DiscoveredMCPTool) return 2;
289	      if (tool instanceof DiscoveredTool) return 1;
290	      return 0; // Built-in
291	    };
292	
293	    this.allKnownTools = new Map(
294	      Array.from(this.allKnownTools.entries()).sort((a, b) => {
295	        const toolA = a[1];
296	        const toolB = b[1];
297	        const priorityA = getPriority(toolA);
298	        const priorityB = getPriority(toolB);
299	
300	        if (priorityA !== priorityB) {
301	          return priorityA - priorityB;
302	        }
303	
304	        if (priorityA === 2) {
305	          // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
306	          const serverA = (toolA as DiscoveredMCPTool).serverName;
307	          // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
308	          const serverB = (toolB as DiscoveredMCPTool).serverName;
309	          return serverA.localeCompare(serverB);
310	        }
311	
312	        return 0;
313	      }),
314	    );
315	  }
